import json, time, urllib.request, urllib.error, datetime, decimal
BASE='http://localhost:8080'

def get_token():
    req=urllib.request.Request(BASE+'/token', method='POST')
    with urllib.request.urlopen(req, timeout=20) as resp:
        return json.load(resp)['token']

token=None

def request(path, method='GET'):
    global token
    while True:
        if token is None:
            token=[REDACTED_SECRET]
        req=urllib.request.Request(BASE+path, method=method, headers={'Authorization':'Bearer '+token})
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            body=e.read().decode(errors='replace')
            if e.code == 401:
                token=None
                continue
            if e.code == 429:
                wait=e.headers.get('Retry-After')
                if wait is None:
                    try: wait=json.loads(body).get('retry_after')
                    except Exception: pass
                delay=float(wait) if wait is not None else 1.0
                time.sleep(max(0,delay))
                continue
            raise RuntimeError(f'{e.code} {path}: {body}')

pages=[]
first=request('/orders?page=1')
total_pages=first['total_pages']
pages.append(first)
for page in range(2,total_pages+1):
    pages.append(request(f'/orders?page={page}'))

seen={}
duplicates=0
for p in pages:
    if p['page'] < 1 or p['total_pages'] "'!= total_pages:
        raise RuntimeError('"'pagination metadata changed')
    for order in p['items']:
        oid=order['id']
        if oid in seen:
            duplicates += 1
        else:
            seen[oid]=order

start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
qual=[]
for order in seen.values():
    if order['status'] "'!= '"'shipped':
        continue
    ts=datetime.datetime.fromisoformat(order['placed_at'].replace('Z','+00:00')).astimezone(datetime.timezone.utc)
    if start <= ts < end:
        qual.append(order)

customers={}
for cid in sorted({o['customer_id'] for o in qual}):
    customers[cid]=request('/customers/'+cid)

by_region={r:0 for r in ['north','south','east','west']}
for o in qual:
    c=customers[o['customer_id']]
    cents=decimal.Decimal(o['amount_cents'])*(decimal.Decimal(100-c['discount_pct'])/decimal.Decimal(100))
    discounted=int(cents.quantize(decimal.Decimal('1'), rounding=decimal.ROUND_HALF_UP))
    by_region[c['region']]+=discounted
result={'total_cents':sum(by_region.values()),'order_count':len(qual),'duplicates_skipped':duplicates,'by_region':by_region}
print(json.dumps({'pages':len(pages),'listed':sum(len(p['items']) for p in pages),'unique_ids':len(seen),'duplicates':duplicates,'qualifying':len(qual),'customers':len(customers),'result':result},sort_keys=True))
with open('/tmp/reconciliation_audit.json','w') as f:
    json.dump({'orders':len(seen),'listed':sum(len(p['items']) for p in pages),'qualifying_ids':[o['id'] for o in qual]},f)
with open('/workspace/result.json','w') as f:
    json.dump(result,f,indent=2)
    f.write('\\n')
